-- DBMS_METADATA.GET_DDL output, trimmed
  CREATE TABLE "HR"."DEPARTMENTS"
   (	"DEPARTMENT_ID" NUMBER(4,0) NOT NULL ENABLE,
	"DEPARTMENT_NAME" VARCHAR2(30 BYTE) CONSTRAINT "DEPT_NAME_NN" NOT NULL ENABLE,
	"MANAGER_ID" NUMBER(6,0),
	 CONSTRAINT "DEPT_ID_PK" PRIMARY KEY ("DEPARTMENT_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "USERS"  ENABLE
   ) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  TABLESPACE "USERS" ;

  CREATE TABLE "HR"."EMPLOYEES"
   (	"EMPLOYEE_ID" NUMBER(6,0) NOT NULL ENABLE,
	"LAST_NAME" VARCHAR2(25 BYTE) NOT NULL ENABLE,
	"SALARY" NUMBER(8,2),
	"DEPARTMENT_ID" NUMBER(4,0),
	 CONSTRAINT "EMP_EMP_ID_PK" PRIMARY KEY ("EMPLOYEE_ID")
  USING INDEX TABLESPACE "USERS"  ENABLE,
	 CONSTRAINT "EMP_DEPT_FK" FOREIGN KEY ("DEPARTMENT_ID")
	  REFERENCES "HR"."DEPARTMENTS" ("DEPARTMENT_ID") ENABLE
   ) TABLESPACE "USERS" ;

  COMMENT ON TABLE "HR"."EMPLOYEES" IS 'Employees of the company';
  COMMENT ON COLUMN "HR"."EMPLOYEES"."SALARY" IS 'Monthly salary';

  CREATE OR REPLACE FORCE VIEW "HR"."EMP_DETAILS_VIEW" ("EMPLOYEE_ID", "LAST_NAME") AS
  SELECT e.employee_id, e.last_name FROM hr.employees e;

  CREATE OR REPLACE PROCEDURE "HR"."ADD_JOB_HISTORY" (p_emp_id NUMBER) IS
  BEGIN
    INSERT INTO job_history (employee_id) VALUES (p_emp_id);
    COMMIT;
  END add_job_history;
/

  CREATE INDEX "HR"."EMP_NAME_IX" ON "HR"."EMPLOYEES" ("LAST_NAME") TABLESPACE "USERS";
